#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

// O(1) - Constant Time
int getFirst(int arr[], int n) {
    return arr[0];  // Always 1 operation, regardless of n
}

// O(log n) - Logarithmic Time
int binarySearch(int arr[], int n, int target) {
    int lo = 0, hi = n - 1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        if (arr[mid] == target) return mid;
        else if (arr[mid] < target) lo = mid + 1;
        else hi = mid - 1;
    }
    return -1;  // Array har step mein half ho raha hai
}

// O(n) - Linear Time
int linearSearch(int arr[], int n, int target) {
    for (int i = 0; i < n; i++) {
        if (arr[i] == target) return i;
    }
    return -1;  // Worst case: saare elements check
}

// O(n^2) - Quadratic Time
void bubbleSort(int arr[], int n) {
    for (int i = 0; i < n - 1; i++) {
        for (int j = 0; j < n - i - 1; j++) {
            if (arr[j] > arr[j + 1])
                swap(arr[j], arr[j + 1]);
        }
    }
}

int main() {
    int arr[] = {1, 3, 5, 7, 9, 11};
    int n = 6;
    cout << "First: " << getFirst(arr, n) << endl;           // O(1)
    cout << "Binary Search 7: " << binarySearch(arr, n, 7) << endl; // O(log n)
    cout << "Linear Search 7: " << linearSearch(arr, n, 7) << endl; // O(n)
    bubbleSort(arr, n);  // O(n^2)
    return 0;
}

