#include <iostream>
using namespace std;

// Linear Search - Best, Worst, Average case analysis
int linearSearch(int arr[], int n, int target) {
    for (int i = 0; i < n; i++) {
        if (arr[i] == target)
            return i;  // Found!
    }
    return -1;  // Not found
}
// Best Case:  O(1)  — target is at arr[0]
// Worst Case: O(n)  — target is at arr[n-1] or not present
// Average:    O(n)  — on average n/2 comparisons

// Insertion Sort - Different cases ka accha example
void insertionSort(int arr[], int n) {
    for (int i = 1; i < n; i++) {
        int key = arr[i];
        int j = i - 1;
        while (j >= 0 && arr[j] > key) {
            arr[j + 1] = arr[j];
            j--;
        }
        arr[j + 1] = key;
    }
}
// Best Case:  O(n)    — already sorted array
// Worst Case: O(n^2)  — reverse sorted array
// Average:    O(n^2)  — random order

int main() {
    int arr[] = {5, 3, 8, 1, 9, 2};
    int n = 6;
    cout << "Search 5 (best): index " << linearSearch(arr, n, 5) << endl;
    cout << "Search 2 (worst): index " << linearSearch(arr, n, 2) << endl;
    cout << "Search 99 (worst): index " << linearSearch(arr, n, 99) << endl;
    return 0;
}

