#include <iostream>
using namespace std;

// T(n) = 2T(n/2) + O(n) => O(n log n) — Merge Sort
void merge(int arr[], int l, int m, int r) {
    int n1 = m - l + 1, n2 = r - m;
    int L[n1], R[n2];
    for (int i = 0; i < n1; i++) L[i] = arr[l + i];
    for (int j = 0; j < n2; j++) R[j] = arr[m + 1 + j];
    int i = 0, j = 0, k = l;
    while (i < n1 && j < n2)
        arr[k++] = (L[i] <= R[j]) ? L[i++] : R[j++];
    while (i < n1) arr[k++] = L[i++];
    while (j < n2) arr[k++] = R[j++];
}

void mergeSort(int arr[], int l, int r) {
    if (l < r) {
        int m = l + (r - l) / 2;
        mergeSort(arr, l, m);       // T(n/2)
        mergeSort(arr, m + 1, r);   // T(n/2)
        merge(arr, l, m, r);        // O(n)
    }
}
// Master Theorem: a=2, b=2, d=1
// log_2(2) = 1 = d => Case 2 => O(n log n)

// T(n) = T(n/2) + O(1) => O(log n) — Binary Search
int binarySearch(int arr[], int l, int r, int x) {
    if (l <= r) {
        int mid = l + (r - l) / 2;
        if (arr[mid] == x) return mid;
        if (arr[mid] > x) return binarySearch(arr, l, mid - 1, x);
        return binarySearch(arr, mid + 1, r, x);
    }
    return -1;
}
// Master Theorem: a=1, b=2, d=0
// log_2(1) = 0 = d => Case 2 => O(log n)

int main() {
    int arr[] = {38, 27, 43, 3, 9, 82, 10};
    int n = 7;
    mergeSort(arr, 0, n - 1);
    cout << "Sorted: ";
    for (int i = 0; i < n; i++) cout << arr[i] << " ";
    cout << endl;
    cout << "Search 43: index " << binarySearch(arr, 0, n - 1, 43) << endl;
    return 0;
}

